var i=[{title:`Pregătește fiecare stație`,text:`Verifică banca, rackul, aparatul sau accesoriul înainte să-l încarci. Reglează corect scaunele și barele de siguranță, folosește inele de blocare când e nevoie și asigură-te că discurile sunt fixate pe ambele părți. Ține genți și accesorii libere departe de pasaje. Dacă nu știi cum funcționează un aparat, roagă personalul să îți arate.`},{title:`Împarte spațiul`,text:`Pune la loc ganterele și discurile, șterge echipamentul cum cere sala și returnează accesoriile cablurilor. Nu ocupa mai multe aparate deodată în orele de vârf. Întreabă politicos dacă poți alterna și stabilește cum schimbați greutatea sau scaunul în siguranță înainte să împărțiți o stație.`},{title:`Ajutoare și siguranțe`,text:`La împinsuri grele de la bancă sau la genuflexiuni, setează brațele de siguranță când poți și folosește un ajutor care știe ce face când ai nevoie. Nu te baza că un străin din apropiere va observa o repetare ratată. Exersează montarea unui rack cu sarcini ușoare înainte să ridici greu și nu intra niciodată în traseul de ridicare al altcuiva.`},{title:`Perioade aglomerate`,text:`Ai o variantă de rezervă pentru echipamentul popular: un ramat cu ganteră poate înlocui un ramat la cablu, iar o genuflexiune goblet poate înlocui o genuflexiune la rack dacă sarcina ți se potrivește în continuare. Antrenamentul tău nu depinde de o anumită stație. O instalație grăbită sau aglomerată nu este totuși un motiv să renunți la tehnică sau să sari peste încălzire.`}];var t=[{label:`Mayo Clinic: siguranța și tehnica antrenamentului cu greutăți`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};